//! The placeholder face (M9 phase 4): actions the preset names but the app
//! cannot do yet stay visible in Find Action (⌘⇧A) and toast "not yet
//! available" on trigger, instead of silently not existing. The per-id status
//! table lives in [`crate::reconcile_data`] (generated by
//! `script/gen-reconcile-data.py`; M14's final audit re-runs it).

use crate::keymap::ACTIVE_PRESET;
use crate::reconcile_data::{STATUS, Status};

/// The status of one preset id (`Na` for ids outside the table — ids can only
/// go missing if the preset and the table drift, which the tests forbid).
#[allow(dead_code)]
pub fn status_of(idea_id: &str) -> Status {
    STATUS.iter().find(|(id, _)| *id == idea_id).map(|(_, status)| *status).unwrap_or(Status::Na)
}

/// The placeholder rows Find Action shows: every `Placeholder` id, title-ized
/// from the action id, with the preset's first keystroke for the secondary
/// column. Sorted by title for a scannable list.
pub fn placeholder_rows() -> Vec<PlaceholderRow> {
    let mut rows: Vec<PlaceholderRow> = STATUS
        .iter()
        .filter(|(_, status)| *status == Status::Placeholder)
        .map(|(id, _)| {
            let keys = ACTIVE_PRESET
                .rows
                .iter()
                .find(|row| row.action == *id)
                .and_then(|row| row.keys.first())
                .copied()
                .unwrap_or("");
            PlaceholderRow { idea_id: id, title: title_of(id), keys }
        })
        .collect();
    rows.sort_by_key(|row| row.title.to_lowercase());
    rows
}

/// One Find Action placeholder row.
#[derive(Clone, Debug)]
pub struct PlaceholderRow {
    pub idea_id: &'static str,
    pub title: String,
    pub keys: &'static str,
}

/// "navigate.gotoClass" → "Goto Class"; "code.expandToLevel1" → "Expand To
/// Level1". Mechanical, for the placeholder rows only — implemented actions
/// carry their own curated titles in the registry.
fn title_of(idea_id: &str) -> String {
    let tail = idea_id.rsplit('.').next().unwrap_or(idea_id);
    let mut words = Vec::new();
    let mut word = String::new();
    for c in tail.chars() {
        if c == '-' {
            if !word.is_empty() {
                words.push(word.clone());
                word.clear();
            }
        } else if c.is_uppercase() {
            if !word.is_empty() {
                words.push(word.clone());
                word.clear();
            }
            word.push(c);
        } else {
            word.push(c);
        }
    }
    if !word.is_empty() {
        words.push(word);
    }
    words
        .iter()
        .map(|word| {
            let mut c = word.chars();
            match c.next() {
                Some(first) => first.to_uppercase().collect::<String>() + c.as_str(),
                None => String::new(),
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The table covers the whole preset (the generator's contract; M14's
    /// audit re-runs the script over the synced preset).
    #[test]
    fn the_table_covers_every_preset_row() {
        assert_eq!(STATUS.len(), ACTIVE_PRESET.rows.len(), "one row per preset id");
        for (row, (id, _)) in ACTIVE_PRESET.rows.iter().zip(STATUS) {
            assert_eq!(row.action, *id, "preset order preserved");
        }
    }

    #[test]
    fn statuses_are_exhaustive_by_construction() {
        // Every id resolves (no accidental Na fallback for a real row).
        for (id, _) in STATUS {
            let found = STATUS.iter().any(|(candidate, _)| candidate == id);
            assert!(found);
        }
        assert_eq!(status_of("navigate.gotoFile"), Status::Done);
        assert_eq!(status_of("code.surroundWith"), Status::Placeholder);
        assert_eq!(status_of("db.execute"), Status::Na);
        assert_eq!(status_of("no.such.id"), Status::Na);
    }

    #[test]
    fn placeholder_rows_carry_preset_keys_and_titles() {
        let rows = placeholder_rows();
        assert!(!rows.is_empty());
        let surround = rows.iter().find(|row| row.idea_id == "code.surroundWith").expect("surround with listed");
        assert_eq!(surround.keys, "Meta+Alt+T");
        assert_eq!(surround.title, "Surround With");
        let titles: Vec<String> = rows.iter().map(|row| row.title.to_lowercase()).collect();
        let mut sorted = titles.clone();
        sorted.sort();
        assert_eq!(titles, sorted, "rows sort by title");
    }

    #[test]
    fn titles_capitalize_camel_case() {
        assert_eq!(title_of("navigate.gotoClass"), "Goto Class");
        assert_eq!(title_of("code.expandToLevel1"), "Expand To Level1");
        assert_eq!(title_of("file.newScratchFile"), "New Scratch File");
    }
}
